-- Gebruik alleen een beoordeelde levering; de meegeleverde CSV is een voorbeeld.
USE Meijendel;
DROP TEMPORARY TABLE IF EXISTS tmp_maatregel_import;
CREATE TEMPORARY TABLE tmp_maatregel_import (plot_id INT,jaar INT,bron VARCHAR(50),deel_label VARCHAR(100),status_code VARCHAR(30),aandeel_pct DECIMAL(5,2),barriere_type VARCHAR(50),geom_wkt LONGTEXT,opmerking VARCHAR(255));
LOAD DATA LOCAL INFILE '/Users/ton/Documents/GitHub/Meijendel/Recreatie/plot_jaar_toegankelijkheid_deel_import.csv' INTO TABLE tmp_maatregel_import FIELDS TERMINATED BY ',' OPTIONALLY ENCLOSED BY '"' LINES TERMINATED BY '\n' IGNORE 1 LINES (@plot_id,@jaar,@bron,@deel_label,@status_code,@aandeel_pct,@barriere_type,@geom_wkt,@opmerking) SET plot_id=@plot_id,jaar=@jaar,bron=@bron,deel_label=@deel_label,status_code=@status_code,aandeel_pct=NULLIF(@aandeel_pct,''),barriere_type=@barriere_type,geom_wkt=NULLIF(@geom_wkt,''),opmerking=NULLIF(TRIM(TRAILING CHAR(13) FROM @opmerking),'');
START TRANSACTION;
INSERT INTO maatregel_brontype VALUES ('handmatige_registratie',NULL,'Oorspronkelijke handmatige bronregistratie') ON DUPLICATE KEY UPDATE brontype_code=brontype_code;
INSERT INTO maatregel_bron(bron_code,brontype_code,titel,raadpleegdatum,bronstatus) SELECT DISTINCT bron,'handmatige_registratie',CONCAT('Beheerregistraties: ',bron),CURRENT_DATE,'aangeleverde_registratie' FROM tmp_maatregel_import ON DUPLICATE KEY UPDATE bron_code=bron_code;
INSERT INTO maatregel_toegankelijkheid_registratie (plot_id,jaar,deel_label,status_code,aandeel_pct,barriere_type,geom_wkt,opmerking,bron_id,niveau) SELECT i.plot_id,i.jaar,i.deel_label,i.status_code,i.aandeel_pct,i.barriere_type,i.geom_wkt,i.opmerking,COALESCE((SELECT MAX(a.bron_id) FROM maatregel_toegankelijkheid_registratie a JOIN maatregel_registratie_herkomst h ON h.toegang_registratie_id=a.registratie_id WHERE h.brontabel='plot_jaar_toegankelijkheid_deel' AND JSON_VALUE(h.oorspronkelijke_rij,'$.bron' RETURNING CHAR(50))=i.bron AND a.plot_id <=> i.plot_id AND a.jaar <=> i.jaar AND a.deel_label <=> i.deel_label),b.bron_id),'deel' FROM tmp_maatregel_import i JOIN maatregel_bron b ON b.bron_code=i.bron WHERE NOT EXISTS (SELECT 1 FROM (SELECT COALESCE(JSON_VALUE(h.oorspronkelijke_rij,'$.id' RETURNING SIGNED NULL ON EMPTY NULL ON ERROR),-a.registratie_id) AS `id`,a.plot_id AS `plot_id`,a.jaar AS `jaar`,COALESCE(JSON_VALUE(h.oorspronkelijke_rij,'$.bron' RETURNING CHAR(50) NULL ON EMPTY NULL ON ERROR),b.bron_code) AS `bron`,a.deel_label AS `deel_label`,a.status_code AS `status_code`,a.aandeel_pct AS `aandeel_pct`,a.barriere_type AS `barriere_type`,a.geom_wkt AS `geom_wkt`,a.opmerking AS `opmerking` FROM maatregel_toegankelijkheid_registratie a JOIN maatregel_bron b USING(bron_id) LEFT JOIN maatregel_registratie_herkomst h ON h.toegang_registratie_id=a.registratie_id AND h.brontabel=CONVERT(X'706c6f745f6a6161725f746f6567616e6b656c696a6b686569645f6465656c' USING utf8mb4) WHERE a.niveau=CONVERT(X'6465656c' USING utf8mb4)) old WHERE old.plot_id <=> i.plot_id AND old.jaar <=> i.jaar AND old.bron <=> i.bron AND old.status_code <=> i.status_code AND old.opmerking <=> i.opmerking AND old.deel_label <=> i.deel_label AND old.aandeel_pct <=> i.aandeel_pct AND old.barriere_type <=> i.barriere_type AND old.geom_wkt <=> i.geom_wkt) ON DUPLICATE KEY UPDATE deel_label=VALUES(deel_label),status_code=VALUES(status_code),aandeel_pct=VALUES(aandeel_pct),barriere_type=VALUES(barriere_type),geom_wkt=VALUES(geom_wkt),opmerking=VALUES(opmerking);
COMMIT;
DROP TEMPORARY TABLE tmp_maatregel_import;
